// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Record the initial owner
        address initialOwner = c.owner();
        // Call setOwner (may revert if msg.sender is not owner)
        vm.prank(initialOwner);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        // The general rule: regardless of success, owner should be unchanged
        assertTrue(c.owner() == initialOwner);
    }
}

