pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // First set owner to caller for this test
        vm.prank(c.owner());
        c.setOwner(caller);
        // Now caller (the owner) tries to set a new owner
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        // If the call succeeded, owner must be newOwner
        assertTrue(!success || c.owner() == newOwner);
    }
}

