import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller == c.owner());
        vm.prank(caller);
        bool success;
        try c.setOwner(newOwner) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == false || c.owner() == caller);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && newOwner != address(0));

        // Get current owner
        address currentOwner = c.owner();

        // Only test when caller is the current owner
        vm.assume(caller == currentOwner);

        // Call setOwner as the current owner
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        // The call should always succeed when caller is the owner
        assertTrue(success);

        // After a successful call to setOwner, owner should equal the newOwner passed as argument
        assertTrue(c.owner() == newOwner);
    }
}

