pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));
        address caller = c.owner();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        if (success) {
            assertTrue(c.owner() == _owner);
        } else {
            assertTrue(c.owner() == caller);
        }
    }
}

